window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["playstation"]={html:"<div class=\"own-playstation\">\n  <a class=\"ps-skip\" href=\"#psMain\">Skip to content</a>\n\n  <!-- ── PRIMARY NAV ─────────────────────────────────────────────────── -->\n  <header class=\"ps-nav\" id=\"psNav\">\n    <div class=\"ps-nav-in\">\n      <a class=\"ps-brand\" href=\"#psMain\" aria-label=\"Northwind home\">\n        <span class=\"ps-brand-mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#0070d1\"/><path d=\"M12 5v11.4M9.4 12.2l2.6 1.9 2.6-1.9M8 19h8\" stroke=\"#fff\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n        </span>\n        <span class=\"ps-brand-name\">Northwind</span>\n      </a>\n      <nav class=\"ps-nav-links\" aria-label=\"Primary\">\n        <a href=\"#psModules\">Modules</a>\n        <a href=\"#psHardware\">Hardware</a>\n        <a href=\"#psPlus\">Plus</a>\n        <a href=\"#psAnniv\">Analytics</a>\n        <a href=\"#psNews\">News</a>\n        <a href=\"#psStore\">Store</a>\n      </nav>\n      <div class=\"ps-nav-actions\">\n        <a class=\"ps-icon\" href=\"#\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg></a>\n        <a class=\"ps-icon\" href=\"#psStore\" aria-label=\"Cart\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 5h2l2 11h10l2-8H7\"/><circle cx=\"9\" cy=\"19\" r=\"1.4\"/><circle cx=\"17\" cy=\"19\" r=\"1.4\"/></svg></a>\n        <a class=\"ps-avatar\" href=\"#\" aria-label=\"Account\">NW</a>\n        <button class=\"ps-burger\" type=\"button\" aria-label=\"Menu\" data-ps-menu aria-expanded=\"false\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n        </button>\n      </div>\n    </div>\n    <div class=\"ps-subnav\" hidden data-ps-drawer>\n      <a href=\"#psModules\">Modules</a><a href=\"#psHardware\">Hardware</a><a href=\"#psPlus\">Plus</a>\n      <a href=\"#psAnniv\">Analytics</a><a href=\"#psNews\">News</a><a href=\"#psStore\">Store</a>\n    </div>\n  </header>\n\n  <main id=\"psMain\">\n    <!-- ── HERO — DARK BAND ───────────────────────────────────────────── -->\n    <section class=\"ps-band ps-band-dark ps-hero\">\n      <div class=\"ps-band-in ps-hero-in\">\n        <div class=\"ps-hero-copy\">\n          <span class=\"ps-badge\">New · 2026 release</span>\n          <h1 class=\"ps-display-xl\">Northwind for every console of your operation.</h1>\n          <p class=\"ps-lead\">One analytics surface for regions, throughput, and revenue. Bring the whole operations stack online — then read it at a glance.</p>\n          <div class=\"ps-hero-cta\">\n            <a class=\"ps-btn ps-btn-primary\" href=\"#psPlus\">Learn more</a>\n            <a class=\"ps-btn ps-btn-secondary-dark\" href=\"#psModules\">Watch the tour</a>\n          </div>\n        </div>\n        <div class=\"ps-console\" aria-label=\"Northwind analytics console\">\n          <div class=\"ps-console-frame\">\n            <div class=\"ps-console-top\">\n              <span class=\"ps-dot\"></span><span class=\"ps-dot\"></span><span class=\"ps-dot\"></span>\n              <span class=\"ps-console-title\">Northwind · Operations</span>\n            </div>\n            <div class=\"ps-console-body\">\n              <div class=\"ps-console-kpi\">\n                <span class=\"ps-console-num\">$48.2k</span>\n                <span class=\"ps-console-lab\">Revenue · weekly</span>\n              </div>\n              <svg class=\"ps-console-chart\" viewBox=\"0 0 320 80\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n                <path d=\"M0 62 L45 54 L90 60 L135 36 L180 42 L225 20 L270 26 L320 10\" fill=\"none\" stroke=\"#0070d1\" stroke-width=\"3.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n              </svg>\n              <div class=\"ps-console-rows\">\n                <div class=\"ps-console-row\"><span>Logistics</span><b>98.4%</b></div>\n                <div class=\"ps-console-row\"><span>Revenue ops</span><b>$48.2k</b></div>\n                <div class=\"ps-console-row\"><span>Support</span><b>4.9★</b></div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── MODULES — DARK RAIL ────────────────────────────────────────── -->\n    <section class=\"ps-band ps-band-dark ps-modules\" id=\"psModules\">\n      <div class=\"ps-band-in\">\n        <div class=\"ps-band-head\">\n          <h2 class=\"ps-display-lg\">Great modules out now — or coming soon</h2>\n          <div class=\"ps-paddles\">\n            <button class=\"ps-paddle\" type=\"button\" data-ps-prev aria-label=\"Previous\"><svg viewBox=\"0 0 24 24\"><path d=\"M15 6l-6 6 6 6\"/></svg></button>\n            <button class=\"ps-paddle\" type=\"button\" data-ps-next aria-label=\"Next\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 6l6 6-6 6\"/></svg></button>\n          </div>\n        </div>\n        <div class=\"ps-rail\" data-ps-rail tabindex=\"0\" aria-label=\"Modules carousel\">\n          <div class=\"ps-rail-track\" data-ps-track></div>\n        </div>\n        <div class=\"ps-dots\" data-ps-dots role=\"group\" aria-label=\"Slide position\"></div>\n      </div>\n    </section>\n\n    <!-- ── HARDWARE — LIGHT CONSOLE SHOWCASE ──────────────────────────── -->\n    <section class=\"ps-band ps-band-light ps-hardware\" id=\"psHardware\">\n      <div class=\"ps-band-in ps-hardware-in\">\n        <div class=\"ps-hardware-copy\">\n          <h2 class=\"ps-display-lg\">Discover all Northwind hardware and accessories.</h2>\n          <p class=\"ps-body\">Deploy on the dashboard console, the field tablet, or the warehouse terminal. Same data everywhere — the surface changes with the shift.</p>\n          <a class=\"ps-btn ps-btn-primary\" href=\"#psStore\">Shop consoles</a>\n        </div>\n        <div class=\"ps-hardware-strip\" id=\"psHardwareStrip\"></div>\n      </div>\n    </section>\n\n    <!-- ── PLUS BANNER ────────────────────────────────────────────────── -->\n    <section class=\"ps-band ps-band-light ps-plus\" id=\"psPlus\">\n      <div class=\"ps-band-in\">\n        <div class=\"ps-plus-banner\">\n          <span class=\"ps-plus-gold\" aria-hidden=\"true\"></span>\n          <div class=\"ps-plus-head\">\n            <h2 class=\"ps-display-md\">Discover Northwind Plus</h2>\n            <p class=\"ps-body-dark\">Three tiers of operations intelligence. Pick the one your team's throughput deserves.</p>\n          </div>\n          <div class=\"ps-tiers\" id=\"psTiers\"></div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── ANNIVERSARY CALLOUT ────────────────────────────────────────── -->\n    <section class=\"ps-band ps-band-light ps-anniv\" id=\"psAnniv\">\n      <div class=\"ps-band-in ps-anniv-in\">\n        <p class=\"ps-eyebrow\">Milestone</p>\n        <h2 class=\"ps-heading-xl\">10 Years of Northwind</h2>\n        <p class=\"ps-body\">A decade of operations teams shipping on the same ledger. The anniversary analytics pack is free for every Plus member this quarter.</p>\n        <a class=\"ps-btn ps-btn-secondary-light\" href=\"#psNews\">Read the retrospective</a>\n      </div>\n    </section>\n\n    <!-- ── ON NORTHWIND — GRADIENT DARK BAND ──────────────────────────── -->\n    <section class=\"ps-band ps-band-on\">\n      <div class=\"ps-band-in ps-on-in\">\n        <h2 class=\"ps-display-xl\">ON NORTHWIND</h2>\n        <p class=\"ps-lead\">Live this week: regional throughput benchmarks, a new forecasting module, and the warehouse terminal beta.</p>\n        <a class=\"ps-btn ps-btn-primary\" href=\"#psNews\">See what's live</a>\n      </div>\n    </section>\n\n    <!-- ── NEWS STRIP — LIGHT ─────────────────────────────────────────── -->\n    <section class=\"ps-band ps-band-light ps-news\" id=\"psNews\">\n      <div class=\"ps-band-in\">\n        <div class=\"ps-band-head ps-band-head-light\">\n          <h2 class=\"ps-display-lg\">From the Northwind blog</h2>\n          <a class=\"ps-link\" href=\"#\">All posts <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg></a>\n        </div>\n        <div class=\"ps-news-grid\" id=\"psNewsGrid\"></div>\n      </div>\n    </section>\n\n    <!-- ── STORE CTA — BLUE BAND ──────────────────────────────────────── -->\n    <section class=\"ps-band ps-band-blue ps-store\" id=\"psStore\">\n      <div class=\"ps-band-in ps-store-in\">\n        <div>\n          <p class=\"ps-store-eyebrow\">Northwind Store</p>\n          <h2 class=\"ps-display-md\">Ready to bring your operations online?</h2>\n        </div>\n        <div class=\"ps-store-actions\">\n          <a class=\"ps-btn ps-btn-commerce\" href=\"#\">Buy now</a>\n          <a class=\"ps-btn ps-btn-secondary-dark\" href=\"#psPlus\">Compare tiers</a>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER — BLUE ───────────────────────────────────────────────── -->\n  <footer class=\"ps-foot\">\n    <div class=\"ps-band-in\">\n      <p class=\"ps-foot-word\">Northwind</p>\n      <div class=\"ps-foot-grid\">\n        <div><p class=\"ps-foot-head\">Store</p><a href=\"#\">Consoles</a><a href=\"#\">Accessories</a><a href=\"#\">Deals</a></div>\n        <div><p class=\"ps-foot-head\">Account</p><a href=\"#\">Sign in</a><a href=\"#\">Plus membership</a></div>\n        <div><p class=\"ps-foot-head\">Support</p><a href=\"#\">Help center</a><a href=\"#\">Status</a></div>\n        <div><p class=\"ps-foot-head\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a></div>\n      </div>\n      <p class=\"ps-foot-fine\">© 2026 · Sample data — showcase only</p>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ PLAYSTATION — Northwind operations analytics, built in PlayStation's real grammar ══\n   Three-canvas chapter system (black / white / PlayStation Blue), SST-weight-300 display,\n   full-pill CTAs, 8px-radius cards, gold gradient reserved for Plus. Scoped under\n   `.own-playstation`. */\n\n.own-playstation {\n  --primary: #0070d1;\n  --primary-pressed: #0064b7;\n  --primary-active: #004d8d;\n  --on-primary: #ffffff;\n  --commerce: #d53b00;\n  --commerce-pressed: #aa2f00;\n  --ink: #000000;\n  --body-light: rgba(0,0,0,.6);\n  --mute-light: #6b6b6b;\n  --ash-light: #cccccc;\n  --canvas-light: #ffffff;\n  --surface-soft: #f3f3f3;\n  --surface-card: #f5f7fa;\n  --canvas-dark: #000000;\n  --surface-dark-elevated: #121314;\n  --surface-dark-card: #181818;\n  --hairline-light: #f3f3f3;\n  --hairline-dark: rgba(229,229,229,.2);\n  --on-dark: #ffffff;\n  --body-dark: rgba(255,255,255,.7);\n  --link-light: #0064b7;\n  --link-dark: #53b1ff;\n  --gold-start: #ffce21;\n  --gold-mid: #f5a623;\n  --gold-end: #ee8e00;\n\n  --f-sst: 'PlayStation SST', 'Roboto', 'Source Sans Pro', 'Arial', 'Helvetica', sans-serif;\n\n  --r-sm: 4px;\n  --r-md: 8px;\n  --r-lg: 16px;\n  --r-full: 9999px;\n  --gut: clamp(16px, 4.6cqi, 48px);\n  --sec: clamp(48px, 7.5cqi, 96px);\n\n  position: relative;\n  background: var(--canvas-dark);\n  color: var(--ink);\n  font-family: var(--f-sst);\n  font-size: 18px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n\n.own-playstation *, .own-playstation *::before, .own-playstation *::after { box-sizing: border-box; }\n.own-playstation p { margin: 0; }\n.own-playstation h1, .own-playstation h2, .own-playstation h3 { margin: 0; font-weight: 300; }\n.own-playstation a { color: inherit; text-decoration: none; }\n.own-playstation img, .own-playstation svg { display: block; }\n.own-playstation button { font: inherit; }\n.own-playstation :focus-visible { outline: 2px solid var(--primary); outline-offset: 3px; border-radius: 6px; }\n.own-playstation .ps-band-dark :focus-visible, .own-playstation .ps-band-blue :focus-visible, .own-playstation .ps-nav :focus-visible { outline-color: #53b1ff; }\n\n.own-playstation .ps-band-in { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n\n.own-playstation .ps-skip {\n  position: absolute; left: 12px; top: -60px; z-index: 60;\n  padding: 10px 16px; border-radius: var(--r-sm); background: var(--canvas-light); color: var(--ink);\n  font-weight: 700; transition: top .2s;\n}\n.own-playstation .ps-skip:focus { top: 12px; }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-playstation .ps-display-xl { font-size: clamp(32px, 5cqi, 54px); line-height: 1.25; letter-spacing: -.1px; }\n.own-playstation .ps-display-lg { font-size: clamp(28px, 4cqi, 44px); line-height: 1.25; letter-spacing: .1px; }\n.own-playstation .ps-display-md { font-size: clamp(24px, 3cqi, 35px); line-height: 1.25; }\n.own-playstation .ps-heading-xl { font-size: clamp(22px, 2.4cqi, 28px); line-height: 1.25; letter-spacing: .1px; }\n.own-playstation .ps-lead { font-size: clamp(16px, 1.5cqi, 18px); line-height: 1.5; }\n.own-playstation .ps-body { font-size: 18px; line-height: 1.5; }\n.own-playstation .ps-body-dark { color: var(--body-dark); }\n.own-playstation .ps-eyebrow { font-size: 12px; font-weight: 500; letter-spacing: .18em; text-transform: uppercase; margin-bottom: 12px; }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-playstation .ps-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 48px; padding: 12px 28px; border-radius: var(--r-full);\n  font-size: 18px; font-weight: 700; letter-spacing: .45px; white-space: nowrap;\n  transition: background-color .15s, transform .15s;\n}\n.own-playstation .ps-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-playstation .ps-btn-primary:hover { background: var(--primary-pressed); }\n.own-playstation .ps-btn-primary:active { background: var(--primary-active); transform: scale(.98); }\n.own-playstation .ps-btn-commerce { background: var(--commerce); color: #fff; }\n.own-playstation .ps-btn-commerce:hover { background: var(--commerce-pressed); }\n.own-playstation .ps-btn-secondary-light { background: transparent; color: var(--ink); box-shadow: inset 0 0 0 1px var(--ash-light); }\n.own-playstation .ps-btn-secondary-light:hover { background: var(--surface-soft); }\n.own-playstation .ps-btn-secondary-dark { background: transparent; color: var(--on-dark); box-shadow: inset 0 0 0 1px var(--hairline-dark); }\n.own-playstation .ps-btn-secondary-dark:hover { background: rgba(255,255,255,.1); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-playstation .ps-nav { position: sticky; top: 68px; z-index: 40; background: var(--canvas-dark); color: var(--on-dark); }\n.own-playstation .ps-nav-in {\n  display: flex; align-items: center; gap: 20px; height: 60px;\n  max-width: 1280px; margin: 0 auto; padding: 0 var(--gut);\n}\n.own-playstation .ps-brand { display: flex; align-items: center; gap: 10px; flex: none; }\n.own-playstation .ps-brand-mark { width: 30px; height: 30px; }\n.own-playstation .ps-brand-name { font-size: 22px; font-weight: 700; letter-spacing: .2px; }\n.own-playstation .ps-nav-links { display: flex; align-items: center; gap: 4px; flex: 1 1 auto; }\n.own-playstation .ps-nav-links a {\n  font-size: 16px; font-weight: 500; letter-spacing: .4px; color: var(--body-dark);\n  padding: 8px 12px; border-radius: var(--r-full);\n}\n.own-playstation .ps-nav-links a:hover { color: var(--on-dark); background: rgba(255,255,255,.1); }\n.own-playstation .ps-nav-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; }\n.own-playstation .ps-icon { display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-full); }\n.own-playstation .ps-icon:hover { background: rgba(255,255,255,.12); }\n.own-playstation .ps-icon svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-playstation .ps-avatar {\n  display: grid; place-items: center; width: 38px; height: 38px; border-radius: var(--r-full);\n  background: var(--primary); color: #fff; font-size: 13px; font-weight: 700;\n}\n.own-playstation .ps-burger { display: none; place-items: center; width: 40px; height: 40px; background: none; border: 0; color: var(--on-dark); cursor: pointer; }\n.own-playstation .ps-burger svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }\n.own-playstation .ps-subnav { display: flex; gap: 20px; padding: 10px var(--gut); border-top: 1px solid var(--hairline-dark); background: var(--surface-dark-elevated); overflow-x: auto; }\n.own-playstation .ps-subnav a { font-size: 14px; color: var(--body-dark); white-space: nowrap; }\n.own-playstation .ps-subnav a:hover { color: var(--on-dark); }\n\n/* ── bands ───────────────────────────────────────────────────────────── */\n.own-playstation .ps-band { padding: var(--sec) 0; }\n.own-playstation .ps-band-dark { background: var(--canvas-dark); color: var(--on-dark); }\n.own-playstation .ps-band-light { background: var(--canvas-light); color: var(--ink); }\n.own-playstation .ps-band-blue { background: var(--primary); color: var(--on-primary); }\n.own-playstation .ps-band-on { background: linear-gradient(180deg, var(--surface-dark-elevated) 0%, var(--canvas-dark) 100%); color: var(--on-dark); }\n.own-playstation .ps-band-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 32px; flex-wrap: wrap; }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-playstation .ps-hero { padding-top: clamp(40px, 6cqi, 96px); }\n.own-playstation .ps-hero-in { display: grid; grid-template-columns: .9fr 1.1fr; gap: clamp(28px, 4cqi, 64px); align-items: center; }\n.own-playstation .ps-hero .ps-lead { color: var(--body-dark); max-width: 46ch; margin: 20px 0 28px; }\n.own-playstation .ps-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }\n.own-playstation .ps-badge {\n  display: inline-block; padding: 4px 10px; border-radius: var(--r-full); background: var(--primary);\n  color: #fff; font-size: 12px; font-weight: 500; margin-bottom: 18px;\n}\n.own-playstation .ps-console { display: grid; place-items: center; }\n.own-playstation .ps-console-frame {\n  width: 100%; max-width: 540px; border-radius: var(--r-lg); overflow: hidden;\n  background: var(--surface-dark-card); box-shadow: 0 40px 80px -40px rgba(0,0,0,.9);\n}\n.own-playstation .ps-console-top { display: flex; align-items: center; gap: 6px; padding: 14px 18px; border-bottom: 1px solid var(--hairline-dark); }\n.own-playstation .ps-dot { width: 9px; height: 9px; border-radius: 50%; background: rgba(255,255,255,.24); }\n.own-playstation .ps-console-title { margin-left: 10px; font-size: 13px; color: var(--body-dark); }\n.own-playstation .ps-console-body { padding: 24px; }\n.own-playstation .ps-console-num { display: block; font-size: 44px; font-weight: 300; line-height: 1; }\n.own-playstation .ps-console-lab { display: block; font-size: 13px; color: var(--body-dark); margin: 4px 0 18px; }\n.own-playstation .ps-console-chart { width: 100%; height: 80px; margin-bottom: 20px; }\n.own-playstation .ps-console-rows { display: grid; gap: 10px; }\n.own-playstation .ps-console-row { display: flex; justify-content: space-between; padding-top: 10px; border-top: 1px solid var(--hairline-dark); font-size: 15px; }\n.own-playstation .ps-console-row span { color: var(--body-dark); }\n.own-playstation .ps-console-row b { font-weight: 700; }\n\n/* ── rail ────────────────────────────────────────────────────────────── */\n.own-playstation .ps-paddles { display: flex; gap: 10px; }\n.own-playstation .ps-paddle { display: grid; place-items: center; width: 48px; height: 48px; border: 0; border-radius: var(--r-full); background: rgba(255,255,255,.16); color: var(--on-dark); cursor: pointer; }\n.own-playstation .ps-paddle:hover { background: rgba(255,255,255,.28); }\n.own-playstation .ps-paddle svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.own-playstation .ps-rail { overflow: hidden; cursor: grab; }\n.own-playstation .ps-rail.is-drag { cursor: grabbing; }\n.own-playstation .ps-rail-track { display: flex; gap: 24px; width: max-content; will-change: transform; }\n.own-playstation .ps-tile {\n  position: relative; flex: none; width: clamp(230px, 22cqi, 300px); aspect-ratio: 16 / 9;\n  border-radius: var(--r-md); overflow: hidden; background: var(--surface-dark-elevated);\n  display: flex; flex-direction: column; justify-content: flex-end; padding: 16px; isolation: isolate; color: var(--on-dark);\n}\n.own-playstation .ps-tile::before { content: ''; position: absolute; inset: 0; z-index: -1; background: linear-gradient(155deg, var(--c, #0070d1) 0%, rgba(0,0,0,.75) 100%); }\n.own-playstation .ps-tile-tag { position: absolute; top: 12px; left: 12px; padding: 4px 10px; border-radius: var(--r-full); background: rgba(0,0,0,.55); font-size: 12px; font-weight: 500; }\n.own-playstation .ps-tile-name { font-size: 20px; font-weight: 500; letter-spacing: .2px; }\n.own-playstation .ps-tile-plat { font-size: 14px; color: var(--body-dark); margin-top: 4px; }\n.own-playstation .ps-dots { display: flex; justify-content: center; gap: 8px; margin-top: 24px; }\n.own-playstation .ps-dot-btn { width: 8px; height: 8px; padding: 0; border: 0; border-radius: 50%; background: rgba(229,229,229,.2); cursor: pointer; }\n.own-playstation .ps-dot-btn.on { background: var(--on-dark); }\n\n/* ── hardware ────────────────────────────────────────────────────────── */\n.own-playstation .ps-hardware-in { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 4cqi, 64px); align-items: center; }\n.own-playstation .ps-hardware .ps-body { color: var(--body-light); max-width: 46ch; margin: 18px 0 26px; }\n.own-playstation .ps-hardware-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-playstation .ps-hw {\n  border-radius: var(--r-md); background: var(--surface-card); padding: 20px; text-align: center;\n  display: grid; gap: 12px; justify-items: center;\n}\n.own-playstation .ps-hw-visual { width: 100%; aspect-ratio: 1; border-radius: var(--r-sm); display: grid; place-items: center; background: linear-gradient(160deg, #dfe7f2, #f5f7fa); }\n.own-playstation .ps-hw-visual svg { width: 46px; height: 46px; fill: none; stroke: var(--primary); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.own-playstation .ps-hw-name { font-size: 15px; font-weight: 700; }\n.own-playstation .ps-hw-meta { font-size: 13px; color: var(--mute-light); }\n\n/* ── plus banner ─────────────────────────────────────────────────────── */\n.own-playstation .ps-plus-banner {\n  position: relative; border-radius: var(--r-md); background: var(--surface-dark-elevated); color: var(--on-dark);\n  padding: clamp(28px, 4cqi, 48px) clamp(20px, 3cqi, 32px); overflow: hidden;\n}\n.own-playstation .ps-plus-gold { position: absolute; top: 0; left: 0; right: 0; height: 6px; background: linear-gradient(90deg, var(--gold-start), var(--gold-mid), var(--gold-end)); }\n.own-playstation .ps-plus-head { max-width: 52ch; margin-bottom: 28px; }\n.own-playstation .ps-tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-playstation .ps-tier { background: var(--surface-dark-card); border-radius: var(--r-md); padding: 22px; display: grid; gap: 14px; }\n.own-playstation .ps-tier-name { font-size: 18px; font-weight: 700; }\n.own-playstation .ps-tier-price { font-size: 28px; font-weight: 300; }\n.own-playstation .ps-tier-price small { font-size: 14px; color: var(--body-dark); }\n.own-playstation .ps-tier ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }\n.own-playstation .ps-tier li { display: flex; gap: 8px; font-size: 15px; color: var(--body-dark); }\n.own-playstation .ps-tier li svg { width: 18px; height: 18px; flex: none; fill: none; stroke: var(--link-dark); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; margin-top: 2px; }\n\n/* ── anniversary / on-band ───────────────────────────────────────────── */\n.own-playstation .ps-anniv-in, .own-playstation .ps-on-in { max-width: 720px; }\n.own-playstation .ps-anniv .ps-body { color: var(--body-light); margin: 16px 0 24px; }\n.own-playstation .ps-anniv .ps-eyebrow { color: var(--primary); }\n.own-playstation .ps-on .ps-lead { color: var(--body-dark); max-width: 52ch; margin: 20px 0 26px; }\n\n/* ── news ────────────────────────────────────────────────────────────── */\n.own-playstation .ps-band-head-light { margin-bottom: 32px; }\n.own-playstation .ps-link { display: inline-flex; align-items: center; gap: 8px; font-size: 16px; color: var(--link-light); font-weight: 500; }\n.own-playstation .ps-link svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.own-playstation .ps-news-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-playstation .ps-news-card { display: grid; gap: 12px; border-radius: var(--r-md); overflow: hidden; }\n.own-playstation .ps-news-thumb { aspect-ratio: 16 / 9; border-radius: var(--r-md); background: linear-gradient(155deg, var(--c, #0070d1), #121314); }\n.own-playstation .ps-news-cat { font-size: 12px; font-weight: 500; letter-spacing: .1em; text-transform: uppercase; color: var(--primary); }\n.own-playstation .ps-news-title { font-size: 22px; line-height: 1.25; }\n.own-playstation .ps-news-date { font-size: 14px; color: var(--mute-light); }\n\n/* ── store / footer ──────────────────────────────────────────────────── */\n.own-playstation .ps-store-in { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }\n.own-playstation .ps-store-eyebrow { font-size: 12px; font-weight: 500; letter-spacing: .18em; text-transform: uppercase; color: rgba(255,255,255,.8); margin-bottom: 10px; }\n.own-playstation .ps-store-actions { display: flex; gap: 12px; flex-wrap: wrap; }\n.own-playstation .ps-foot { background: var(--primary); color: var(--on-primary); padding: clamp(32px, 5cqi, 48px) 0; }\n.own-playstation .ps-foot-word { font-size: 30px; font-weight: 700; letter-spacing: .2px; margin-bottom: 24px; }\n.own-playstation .ps-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-playstation .ps-foot-grid > div { display: flex; flex-direction: column; gap: 10px; }\n.own-playstation .ps-foot-head { font-size: 14px; font-weight: 700; margin-bottom: 4px; }\n.own-playstation .ps-foot-grid a { font-size: 14px; color: rgba(255,255,255,.8); }\n.own-playstation .ps-foot-grid a:hover { color: #fff; }\n.own-playstation .ps-foot-fine { margin-top: 28px; font-size: 12px; color: rgba(255,255,255,.75); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-playstation .ps-hardware-strip { grid-template-columns: repeat(3, 1fr); }\n  .own-playstation .ps-nav-links { display: none; }\n  .own-playstation .ps-burger { display: grid; }\n}\n@container frame (max-width: 760px) {\n  .own-playstation .ps-hero-in, .own-playstation .ps-hardware-in { grid-template-columns: 1fr; }\n  .own-playstation .ps-tiers { grid-template-columns: 1fr; }\n  .own-playstation .ps-news-grid { grid-template-columns: 1fr; }\n  .own-playstation .ps-foot-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-playstation .ps-paddles { display: none; }\n  .own-playstation .ps-hardware-strip { grid-template-columns: repeat(3, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-playstation .ps-hero-cta { flex-direction: column; }\n  .own-playstation .ps-hero-cta .ps-btn { width: 100%; }\n  .own-playstation .ps-hardware-strip { grid-template-columns: 1fr 1fr; }\n  .own-playstation .ps-store-in { flex-direction: column; align-items: flex-start; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-playstation *, .own-playstation *::before, .own-playstation *::after {\n    animation-duration: .001ms !important; transition-duration: .001ms !important;\n  }\n}\n"};
/* ══ PLAYSTATION — Northwind operations analytics ═════════════════════════════════
   Registers window.OWN_LAYOUTS['playstation'].init(root). Renders the module rail,
   hardware strip, Plus tiers and news grid; drives the rail carousel with paddles,
   drag and dots. Returns a cleanup that removes every listener and rAF. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  var MODULES = [
    { name: 'Throughput Benchmarks', plat: 'Regions · desktop', tag: 'New', c: '#0070d1' },
    { name: 'Forecasting Module', plat: 'Planning · all consoles', tag: 'Coming soon', c: '#7928ca' },
    { name: 'Warehouse Terminal', plat: 'Field · beta', tag: 'Beta', c: '#d53b00' },
    { name: 'Support Health', plat: 'Service · desktop', tag: 'Live', c: '#0fa58c' },
    { name: 'Revenue Pulse', plat: 'Finance · all consoles', tag: 'Live', c: '#0070d1' },
    { name: 'Capacity Planner', plat: 'Teams · desktop', tag: 'New', c: '#2c8c66' }
  ];

  var HW = [
    { name: 'Dashboard Console', meta: 'Ops desk · 27"', d: 'M4 5h16v10H4zM8 19h8M12 15v4' },
    { name: 'Field Tablet', meta: 'Warehouse · 11"', d: 'M7 3h10v18H7zM11 18h2' },
    { name: 'Terminal Hub', meta: 'Floor · wall mount', d: 'M4 4h16v12H4zM9 20h6M12 16v4' }
  ];

  var TIERS = [
    { name: 'Essential', price: '$29', per: '/seat / mo', feats: ['6 regions', 'Weekly dashboards', 'Email alerts'] },
    { name: 'Performance', price: '$59', per: '/seat / mo', feats: ['Unlimited regions', 'Forecasting module', 'Priority support'] },
    { name: 'Enterprise', price: 'Custom', per: '', feats: ['SSO & audit log', 'Dedicated onboarding', 'SLA 99.95%'] }
  ];

  var NEWS = [
    { cat: 'Analytics', title: 'Regional throughput benchmarks are live for all tiers', date: 'Mar 12, 2026', c: '#0070d1' },
    { cat: 'Product', title: 'The forecasting module enters open beta this quarter', date: 'Mar 04, 2026', c: '#7928ca' },
    { cat: 'Engineering', title: 'How Northwind keeps six regions on one ledger', date: 'Feb 26, 2026', c: '#0fa58c' }
  ];

  OWN['playstation'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var rafs = [];
      var $ = function (s) { return root.querySelector(s); };
      var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }

      /* ── static content ─────────────────────────────────────────────── */
      var track = $('[data-ps-track]');
      if (track) {
        track.innerHTML = MODULES.map(function (m) {
          return '<article class="ps-tile" style="--c:' + esc(m.c) + '">'
            + '<span class="ps-tile-tag">' + esc(m.tag) + '</span>'
            + '<span class="ps-tile-name">' + esc(m.name) + '</span>'
            + '<span class="ps-tile-plat">' + esc(m.plat) + '</span></article>';
        }).join('');
      }

      var hw = $('#psHardwareStrip');
      if (hw) {
        hw.innerHTML = HW.map(function (h) {
          return '<div class="ps-hw">'
            + '<div class="ps-hw-visual"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + esc(h.d) + '"/></svg></div>'
            + '<span class="ps-hw-name">' + esc(h.name) + '</span>'
            + '<span class="ps-hw-meta">' + esc(h.meta) + '</span></div>';
        }).join('');
      }

      var tiers = $('#psTiers');
      if (tiers) {
        tiers.innerHTML = TIERS.map(function (t) {
          return '<div class="ps-tier">'
            + '<span class="ps-tier-name">' + esc(t.name) + '</span>'
            + '<span class="ps-tier-price">' + esc(t.price) + ' <small>' + esc(t.per) + '</small></span>'
            + '<ul>' + t.feats.map(function (f) {
              return '<li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12l4 4 10-10"/></svg>' + esc(f) + '</li>';
            }).join('') + '</ul>'
            + '<a class="ps-btn ps-btn-primary" href="#psStore">Choose ' + esc(t.name) + '</a></div>';
        }).join('');
      }

      var news = $('#psNewsGrid');
      if (news) {
        news.innerHTML = NEWS.map(function (n) {
          return '<a class="ps-news-card" href="#" style="--c:' + esc(n.c) + '">'
            + '<span class="ps-news-thumb" aria-hidden="true"></span>'
            + '<span class="ps-news-cat">' + esc(n.cat) + '</span>'
            + '<span class="ps-news-title">' + esc(n.title) + '</span>'
            + '<span class="ps-news-date">' + esc(n.date) + '</span></a>';
        }).join('');
      }

      /* ── rail carousel ──────────────────────────────────────────────── */
      var rail = $('[data-ps-rail]');
      var dotsEl = $('[data-ps-dots]');
      var pos = 0, max = 0, dragging = false, startX = 0, startPos = 0, moved = 0, vx = 0, lastX = 0, lastT = 0;
      var glideRaf = 0;

      function measure() { if (rail && track) max = Math.max(0, track.scrollWidth - rail.clientWidth); }
      function apply() {
        if (!track || !rail) return;
        pos = Math.max(-max, Math.min(0, pos));
        track.style.transform = 'translate3d(' + pos + 'px,0,0)';
        var card = track.firstElementChild;
        var w = card ? card.offsetWidth + 24 : 300;
        var per = Math.max(1, Math.round(rail.clientWidth / w));
        var pages = Math.max(1, Math.ceil(track.children.length / per));
        var idx = max ? Math.min(pages - 1, Math.round((-pos / max) * (pages - 1))) : 0;
        $$('.ps-dot-btn').forEach(function (d, i) { d.classList.toggle('on', i === idx); });
      }
      function stepBy(dir) {
        if (!track) return;
        var card = track.firstElementChild;
        var w = card ? card.offsetWidth + 24 : 300;
        pos += dir * -w * 2;
        track.style.transition = 'transform .5s cubic-bezier(.16,1,.3,1)';
        apply();
        window.setTimeout(function () { if (track) track.style.transition = ''; }, 520);
      }
      function glide() {
        if (Math.abs(vx) < 0.3 || dragging) return;
        pos += vx; vx *= 0.94; apply();
        glideRaf = raf(glide);
      }

      if (rail && dotsEl) {
        var card0 = track ? track.children.length : 0;
        dotsEl.innerHTML = '';
        var per0 = 4;
        var pages0 = Math.max(1, Math.ceil(card0 / per0));
        for (var i = 0; i < pages0; i++) {
          (function (n) {
            var b = document.createElement('button');
            b.type = 'button'; b.className = 'ps-dot-btn' + (n === 0 ? ' on' : '');
            b.setAttribute('aria-label', 'Go to slide ' + (n + 1));
            on(b, 'click', function () {
              measure();
              var card = track.firstElementChild;
              var w = card ? card.offsetWidth + 24 : 300;
              pos = -n * w * per0;
              track.style.transition = 'transform .5s cubic-bezier(.16,1,.3,1)';
              apply();
              window.setTimeout(function () { if (track) track.style.transition = ''; }, 520);
            });
            dotsEl.appendChild(b);
          })(i);
        }

        on(rail, 'pointerdown', function (e) {
          dragging = true; moved = 0; startX = e.clientX; startPos = pos; lastX = e.clientX; lastT = performance.now(); vx = 0;
          rail.classList.add('is-drag');
        });
        on(window, 'pointermove', function (e) {
          if (!dragging) return;
          pos = startPos + (e.clientX - startX);
          moved = Math.max(moved, Math.abs(e.clientX - startX));
          var t = performance.now();
          vx = ((e.clientX - lastX) / Math.max(1, t - lastT)) * 16;
          lastX = e.clientX; lastT = t;
          apply();
        });
        on(window, 'pointerup', function () {
          if (!dragging) return;
          dragging = false; rail.classList.remove('is-drag'); glide();
        });
        on(rail, 'click', function (e) { if (moved > 6) { e.preventDefault(); e.stopPropagation(); } }, true);
        on(rail, 'keydown', function (e) {
          if (e.key === 'ArrowRight') { e.preventDefault(); stepBy(1); }
          if (e.key === 'ArrowLeft') { e.preventDefault(); stepBy(-1); }
        });
        on($('[data-ps-next]'), 'click', function () { stepBy(1); });
        on($('[data-ps-prev]'), 'click', function () { stepBy(-1); });
        if ('ResizeObserver' in window) {
          var ro = new ResizeObserver(function () { measure(); apply(); });
          ro.observe(rail);
          var ro2 = new ResizeObserver(function () { measure(); apply(); });
          ro2.observe(root);
          var dis = function () { try { ro.disconnect(); ro2.disconnect(); } catch (err) {} };
        }
        raf(function () { measure(); apply(); });
      }

      /* ── mobile menu ────────────────────────────────────────────────── */
      var burger = $('[data-ps-menu]');
      var drawer = $('[data-ps-drawer]');
      on(burger, 'click', function () {
        if (!drawer) return;
        var open = drawer.hidden;
        drawer.hidden = !open;
        burger.setAttribute('aria-expanded', String(open));
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) {} }
        if (glideRaf) cancelAnimationFrame(glideRaf);
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        if (typeof dis === 'function') dis();
      };
    }
  };
})();
